head.script:
tailwind.config = {
    theme: {
        extend: {
            colors: {
                primary: '#3b82f6',
                success: '#22c55e',
                warning: '#f59e0b',
            }
        }
    }
}

body.script:
document.addEventListener('DOMContentLoaded', function() {
    const scheduleData = ;
    const allEmployees = ;
    let currentStartDate = scheduleData.start_date;
    let selectedCell = null;
    let selectedEmployee = null;

    // Navigation
    document.getElementById('btnPrevWeek').addEventListener('click', function() {
        const date = new Date(currentStartDate);
        date.setDate(date.getDate() - 7);
        window.location.href = '/shift-schedule?start_date=' + date.toISOString().split('T')[0];
    });

    document.getElementById('btnNextWeek').addEventListener('click', function() {
        const date = new Date(currentStartDate);
        date.setDate(date.getDate() + 7);
        window.location.href = '/shift-schedule?start_date=' + date.toISOString().split('T')[0];
    });

    // Click nút thêm nhân viên
    document.querySelectorAll('.btn-add-employee').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            selectedCell = this.closest('.schedule-cell');
            openAddEmployeeModal();
        });
    });

    // Click nút xóa
    document.querySelectorAll('.btn-remove-emp').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();
            if (!confirm('')) return;

            const chip = this.closest('div');
            const registrationId = chip.dataset.registrationId;

            fetch('/shift-schedule/remove-employee', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {registration_id: registrationId}
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result && data.result.success) {
                    chip.remove();
                } else {
                    alert(' ' + (data.result ? data.result.message : ''));
                }
            });
        });
    });

    // Click nút duyệt
    document.querySelectorAll('.btn-approve-emp').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();

            const chip = this.closest('div');
            const registrationId = chip.dataset.registrationId;

            fetch('/shift-schedule/approve', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {registration_id: registrationId}
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result && data.result.success) {
                    location.reload();
                } else {
                    alert(' ' + (data.result ? data.result.message : ''));
                }
            });
        });
    });

    // Click nút từ chối
    document.querySelectorAll('.btn-reject-emp').forEach(btn => {
        btn.addEventListener('click', function(e) {
            e.stopPropagation();

            const chip = this.closest('div');
            const registrationId = chip.dataset.registrationId;

            fetch('/shift-schedule/reject', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({
                    jsonrpc: '2.0',
                    method: 'call',
                    params: {registration_id: registrationId}
                })
            })
            .then(response => response.json())
            .then(data => {
                if (data.result && data.result.success) {
                    location.reload();
                } else {
                    alert(' ' + (data.result ? data.result.message : ''));
                }
            });
        });
    });

    // Modal functions
    function openAddEmployeeModal() {
        selectedEmployee = null;
        document.getElementById('employeeSearch').value = '';
        renderEmployeeList('');
        document.getElementById('addEmployeeModal').classList.remove('hidden');
    }

    function closeModal() {
        document.getElementById('addEmployeeModal').classList.add('hidden');
    }

    document.getElementById('btnCloseModal').addEventListener('click', closeModal);
    document.querySelector('.btn-close-modal').addEventListener('click', closeModal);

    document.getElementById('employeeSearch').addEventListener('input', function() {
        renderEmployeeList(this.value.toLowerCase());
    });

    function renderEmployeeList(filter) {
        const list = document.getElementById('employeeList');
        const existingIds = getExistingEmployeeIds(selectedCell);

        list.innerHTML = '';
        allEmployees.forEach(emp => {
            if (existingIds.includes(emp.id)) return;
            if (filter && !emp.name.toLowerCase().includes(filter)) return;

            const item = document.createElement('div');
            const isSelected = selectedEmployee === emp.id;
            item.className = 'p-3 rounded-xl border cursor-pointer transition ' + 
                (isSelected ? 'bg-blue-50 border-primary' : 'border-slate-200 hover:border-primary hover:bg-slate-50');
            item.dataset.employeeId = emp.id;
            item.innerHTML = '' + emp.name + '';
            item.addEventListener('click', function() {
                const id = parseInt(this.dataset.employeeId);
                selectedEmployee = id;
                renderEmployeeList(filter);
            });
            list.appendChild(item);
        });
    }

    function getExistingEmployeeIds(cell) {
        const ids = [];
        cell.querySelectorAll('[data-employee-id]').forEach(chip => {
            ids.push(parseInt(chip.dataset.employeeId));
        });
        return ids;
    }

    document.getElementById('btnAddEmployee').addEventListener('click', function() {
        if (!selectedCell || !selectedEmployee) {
            alert('');
            return;
        }

        const date = selectedCell.dataset.date;
        const shiftId = selectedCell.dataset.shiftId;

        fetch('/shift-schedule/add-employee', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {date: date, shift_id: shiftId, employee_id: selectedEmployee}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                location.reload();
            } else {
                alert(' ' + (data.result ? data.result.message : ''));
            }
        });
    });

    // Duyệt tất cả
    document.getElementById('btnApproveAll').addEventListener('click', function() {
        if (!confirm('')) return;

        this.disabled = true;
        this.innerHTML = ' ';

        fetch('/shift-schedule/approve-all', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                jsonrpc: '2.0',
                method: 'call',
                params: {start_date: currentStartDate}
            })
        })
        .then(response => response.json())
        .then(data => {
            if (data.result && data.result.success) {
                alert(data.result.message);
                location.reload();
            } else {
                alert(' ' + (data.result ? data.result.message : ''));
            }
            this.disabled = false;
            this.innerHTML = ' ';
        });
    });
});
